create extension if not exists pgcrypto;
create table if not exists public.profiles(id uuid primary key references auth.users(id) on delete cascade,role text not null default 'student',display_name text default '',class_name text default '',created_at timestamptz default now());
create table if not exists public.subjects(id uuid primary key default gen_random_uuid(),name text not null,icon text default '📚',color text default '#6d5dfc',description text default '',sort_order int default 0,is_active boolean default true,created_by uuid references auth.users(id),created_at timestamptz default now());
create table if not exists public.questions(id uuid primary key default gen_random_uuid(),content text not null,option_a text default '',option_b text default '',option_c text default '',option_d text default '',correct_answer text default 'A',difficulty text default 'Nhận biết',explanation text default '',created_at timestamptz default now());
create table if not exists public.exams(id uuid primary key default gen_random_uuid(),title text not null,subject_id uuid references public.subjects(id) on delete set null,duration_minutes int default 45,question_count int default 0,is_open boolean default false,ranking_enabled boolean default true,ranking_mode text default 'best',created_at timestamptz default now());
create table if not exists public.exam_questions(id uuid primary key default gen_random_uuid(),exam_id uuid references public.exams(id) on delete cascade,question_id uuid references public.questions(id) on delete cascade,position int default 0);
create table if not exists public.results(id uuid primary key default gen_random_uuid(),exam_id uuid references public.exams(id) on delete set null,student_name text not null,student_class text default '',score numeric(6,2) default 0,correct_count int default 0,total_questions int default 0,duration_seconds int default 0,created_at timestamptz default now());
